{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret stemmer med rubrikken og kilderne. Flere ansøgte funktionsnedsættelser vurderes samlet. Udgangspunktet er, at kun de angivne varige funktionsnedsættelser vurderes. Journalomtale alene inddrager dem ikke automatisk. En yderligere funktionsnedsættelse kan inddrages under sagen, hvis ansøgeren beder om det og indsender tilstrækkelig dokumentation. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: samlet vurdering, krav om at angive og dokumentere, udgangspunktet om kun angivne funktionsnedsættelser, og senere inddragelse efter ønske og tilstrækkelig dokumentation. Det understøttende element om journalomtale er også med."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke funktionsnedsættelser Udbetaling Danmark vurderer, når der er flere."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken en bestemmelse eller vejledningen. Det er kun almindelig tekst."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilderne understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle væsentlige påstande har støtte i vejledningens afsnit 3.4.1.2 og 3.5 og i SU-bekendtgørelsens § 37, stk. 2. Der er ikke tilføjet nye regler, betingelser eller undtagelser."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'som udgangspunkt', kravet om tilstrækkelig dokumentation for en senere funktionsnedsættelse og pointen om, at journalomtale ikke automatisk inddrager andre funktionsnedsættelser. Varighed er nævnt i udgangspunktet. Kravet om, at minimumskravene til dokumentation er opfyldt, er dækket af 'tilstrækkelig dokumentation'."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er sammenhængende. Udgangspunktet om angivne funktionsnedsættelser, den samlede vurdering og undtagelsen for senere tilføjelser er ikke indbyrdes modstridende, og konklusionen følger af dem."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Som udgangspunkt', 'skal oplyse', 'inddrages ikke automatisk' og 'kan ... bede om' gengiver kilderne præcist. Svaret gør ikke skøn eller undtagelser absolutte."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "yes",
      "reason": "Svaret siger, at Udbetaling Danmark foretager en samlet vurdering, når der søges på flere funktionsnedsættelser, og at ansøgeren skal oplyse om dem og dokumentere hver."
    },
    "A24": {
      "label": "yes",
      "reason": "Svaret siger, at kun de funktionsnedsættelser, der er angivet i ansøgningen, vurderes som udgangspunkt. Andre, der blot nævnes i lægefaglig dokumentation, inddrages ikke automatisk."
    },
    "A25": {
      "label": "partial",
      "reason": "Svaret dækker, at ansøgeren under sagen kan få en yderligere funktionsnedsættelse inddraget med tilstrækkelig dokumentation, og at det sker på ansøgerens ønske. Det nævner ikke eksplicit kravet om varighed eller minimumskravene til dokumentation, og 'tilstrækkelig dokumentation' dækker dem kun delvist."
    }
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet i forhold til rubrikken. Svaret citerer dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kildereglen."
}

